    /// Errors from ABI encoding and typed decoding.
    public enum WrapperError: Error {
        /// The SDK could not encode a value.
        case encodingFailed(String)
        /// The decoded value differs from the ABI type.
        case invalidValue(String)
        /// The SDK cannot represent this ABI shape.
        case unsupported(String)
        /// The log does not match this event.
        case eventMismatch
    }

    private static func _cast<T>(_ raw: Any, as type: T.Type) throws -> T {
        guard let value = raw as? T else { throw WrapperError.invalidValue(String(describing: type)) }
        return value
    }
    private static func _array<T>(_ raw: Any, _ convert: (Any) throws -> T) throws -> [T] {
        guard let values = raw as? [Any] else { throw WrapperError.invalidValue("array") }
        return try values.map(convert)
    }
    private static func _contract() throws -> EthereumContract { try EthereumContract(abi) }

    private static func _encodeDeploymentInfo(_ value: DeploymentInfo) -> [Any] { [value.stateTag, value.deadlineOrLiveBlock, value.windowCloseBlock, value.slashReason] }
    private static func _validateDeploymentInfo(_ value: DeploymentInfo) throws {
        guard value.stateTag < (BigUInt(1) << 8) else { throw WrapperError.encodingFailed("uint8 out of range") }
        guard value.deadlineOrLiveBlock < (BigUInt(1) << 64) else { throw WrapperError.encodingFailed("uint64 out of range") }
        guard value.windowCloseBlock < (BigUInt(1) << 64) else { throw WrapperError.encodingFailed("uint64 out of range") }
        guard value.slashReason < (BigUInt(1) << 8) else { throw WrapperError.encodingFailed("uint8 out of range") }
    }
    private static func _decodeDeploymentInfo(_ raw: Any) throws -> DeploymentInfo {
        guard let values = raw as? [Any], values.count == 4 else { throw WrapperError.invalidValue("DeploymentInfo") }
        return DeploymentInfo(stateTag: try _cast(values[0], as: BigUInt.self), deadlineOrLiveBlock: try _cast(values[1], as: BigUInt.self), windowCloseBlock: try _cast(values[2], as: BigUInt.self), slashReason: try _cast(values[3], as: BigUInt.self))
    }

    private static func _encodeRiskTierInput(_ value: RiskTierInput) -> [Any] { [value.maxNotional, value.maxLeverage, value.maintenanceMarginBps] }
    private static func _validateRiskTierInput(_ value: RiskTierInput) throws {
        guard value.maxNotional < (BigUInt(1) << 64) else { throw WrapperError.encodingFailed("uint64 out of range") }
        guard value.maxLeverage < (BigUInt(1) << 8) else { throw WrapperError.encodingFailed("uint8 out of range") }
        guard value.maintenanceMarginBps < (BigUInt(1) << 16) else { throw WrapperError.encodingFailed("uint16 out of range") }
    }
    private static func _decodeRiskTierInput(_ raw: Any) throws -> RiskTierInput {
        guard let values = raw as? [Any], values.count == 3 else { throw WrapperError.invalidValue("RiskTierInput") }
        return RiskTierInput(maxNotional: try _cast(values[0], as: BigUInt.self), maxLeverage: try _cast(values[1], as: BigUInt.self), maintenanceMarginBps: try _cast(values[2], as: BigUInt.self))
    }

    private static func _encodePerpPolicy(_ value: PerpPolicy) -> [Any] { [value.revision, value.backstopTopupBps, value.tiers.map { item in _encodeRiskTierInput(item) }] }
    private static func _validatePerpPolicy(_ value: PerpPolicy) throws {
        guard value.revision < (BigUInt(1) << 64) else { throw WrapperError.encodingFailed("uint64 out of range") }
        guard value.backstopTopupBps < (BigUInt(1) << 16) else { throw WrapperError.encodingFailed("uint16 out of range") }
        for item in value.tiers {
            try _validateRiskTierInput(item)
        }
    }
